import { SVGProps, useMemo } from "react";
import styled from "styled-components";

export type IconDefinition = {
    path: string;
    stroke?: number;
    dash?: string;
};

type LayerPlacement = "full" | "top-left" | "top-right" | "bottom-left" | "bottom-right";

// possible future enhancement, make badges (and the related cutouts) relative coordinates instead, and use this as a prefix to set the badge position.
/*
const POSITIONS = {
    bl: "M144,496",
    tl: "M144,144",
    tr: "M496,144",
    br: "M496,496",
};
*/

const PLACEMENTS = {
    full: { x: 0, y: 0, size: 640 },
    "top-left": { x: 0, y: 0, size: 288 },
    "top-right": { x: 352, y: 0, size: 288 },
    "bottom-left": { x: 0, y: 352, size: 288 },
    "bottom-right": { x: 352, y: 352, size: 288 },
};

type Cutout = "circle" | "square" | "diamond" | "bevel" | "scoop" | "hexagonH" | "hexagonV" | "pillV" | "pillH" | "slash";

type IconProps = {
    color?: string;
    cutout?: Cutout;
    shape: IconDefinition | IconDefinition[];
    layer?: IconDefinition;
    layerColor?: string;
    layerPlacement?: LayerPlacement;
};

const Base = styled(({ color = "var(--icon)", cutout, layer, layerColor = color, shape, layerPlacement = "bottom-left", className, ...props }: SVGProps<SVGSVGElement> & IconProps) => {
    const colors = useMemo(() => {
        return color.split(" ");
    }, [color]);

    const theShape = useMemo(() => {
        return Array.isArray(shape) ? shape : [shape];
    }, [shape]);

    const cssStyle = useMemo(() => {
        return cutout ? { clipPath: `path(evenodd, "M0 0L640 0L640 640L0 640Z ${CUTOUTS[layerPlacement][cutout]}") view-box` } : {};
    }, [cutout, layerPlacement]);

    return (
        <svg {...props} viewBox={"0 0 640 640"} className={`${className ?? ""} meta-icon`}>
            <g style={cssStyle}>
                {theShape.map((each, i) => {
                    return (
                        <path
                            key={i}
                            fill={"stroke" in each ? undefined : (colors?.[i] ?? colors[0])}
                            d={each.path}
                            stroke={"stroke" in each ? (colors?.[i] ?? colors[0]) : undefined}
                            strokeWidth={"stroke" in each ? each.stroke : undefined}
                            strokeDasharray={"dash" in each ? each.dash : undefined}
                        />
                    );
                })}
            </g>
            {layer ? (
                <svg x={PLACEMENTS[layerPlacement].x} y={PLACEMENTS[layerPlacement].y} width={PLACEMENTS[layerPlacement].size} height={PLACEMENTS[layerPlacement].size} viewBox="0 0 640 640">
                    <path fill={layerColor} d={layer.path} />
                </svg>
            ) : null}
        </svg>
    );
})`
    width: 1lh;
    height: 1lh;
    aspect-ratio: 1;
    display: inline-flex;
    vertical-align: middle;
    fill: none;
    overflow: visible;
    & * {
        vector-effect: non-scaling-stroke;
        stroke-width: 1.5px;
    }
`;

const IconStack = styled((props: SVGProps<SVGSVGElement>) => {
    return <svg {...props} viewBox={"0 0 640 640"} />;
})`
    width: 1lh;
    height: 1lh;
    aspect-ratio: 1;
    display: inline-flex;
    vertical-align: middle;
    fill: none;
    overflow: visible;
    & * {
        vector-effect: non-scaling-stroke;
        stroke-width: 1.5px;
    }
`;

type ToExport = typeof Base & {
    Stack: typeof IconStack;
};
export const Icon = Base as ToExport;
Icon.Stack = IconStack;

